mapper.select:
SELECT aa.id, aa.activity_id as activityId, va.activity_name as activityName, aa.volunteer_id as userId, m.nickname as userName, m.nickname as userNickname, m.phone as userPhone, aa.status, aa.apply_time as applyTime, aa.review_time as reviewTime, aa.reviewer_id as reviewerId, r.nickname as reviewerName, r.nickname as reviewerNickname, aa.created_at as createdAt, aa.updated_at as updatedAt FROM activity_application aa LEFT JOIN volunteer_activity va ON aa.activity_id = va.id LEFT JOIN members m ON aa.volunteer_id = m.id LEFT JOIN members r ON aa.reviewer_id = r.id WHERE aa.del = 0
AND aa.activity_id = #{activityId}
AND aa.volunteer_id = #{userId}
AND aa.status = #{status}
ORDER BY aa.apply_time DESC

SELECT aa.id, aa.activity_id as activityId, va.activity_name as activityName, aa.volunteer_id as userId, m.nickname as userName, m.nickname as userNickname, m.phone as userPhone, aa.status, aa.apply_time as applyTime, aa.review_time as reviewTime, aa.reviewer_id as reviewerId, r.nickname as reviewerName, r.nickname as reviewerNickname, aa.created_at as createdAt, aa.updated_at as updatedAt FROM activity_application aa LEFT JOIN volunteer_activity va ON aa.activity_id = va.id AND va.initiator_id = #{issuerId} LEFT JOIN members m ON aa.volunteer_id = m.id LEFT JOIN members r ON aa.reviewer_id = r.id WHERE aa.del = 0 AND va.id IS NOT NULL
AND aa.status = #{status}
ORDER BY aa.apply_time DESC
